Pseudo-code:
```typescript
export async function extractContent(url: string): Promise<ExtractionResult> {
  const logger = new ExtractionLogger();
  const retryConfig = {
    maxAttempts: 3,
    baseDelay: 1,
    retryableErrors: [ErrorType.FETCH_ERROR, ErrorType.TIMEOUT_ERROR, ErrorType.PARSE_ERROR]
  };

  return withRetry(async () => {
    // Fetch stage
    logger.logStageStart('fetch');
    const html = await fetchWithTimeout(url);
    logger.logStageEnd('fetch');

    // Parse stage
    logger.logStageStart('parse');
    const content = parseContentWithFallback(html, logger);
    logger.logStageEnd('parse');

    // Convert stage
    logger.logStageStart('convert');
    const markdown = await convertToMarkdownWithFallback(content, logger);
    logger.logStageEnd('convert');

    return { content: markdown, url };
  }, retryConfig, logger);
}

function convertToMarkdownWithFallback(html: string, logger: ExtractionLogger): string {
  try {
    return convertHtmlToMarkdown(html);
  } catch (error) {
    logger.logStageEnd('convert (fallback to plain text)');
    return html.replace(/<[^>]*>/g, ''); // Strip HTML tags
  }
}
```

